const d={A:1,I:1,J:1,Q:1,Y:1,B:2,K:2,R:2,C:3,G:3,L:3,S:3,D:4,M:4,T:4,E:5,H:5,N:5,X:5,U:6,V:6,W:6,O:7,Z:7,F:8,P:8};function h(n){return d[n.toUpperCase()]||0}function c(n){const t=n.toUpperCase().replace(/[^A-Z]/g,"").split("").reduce((e,u)=>e+h(u),0);return f(t)}function f(n){let t=n;for(;t>9;)t=t.toString().split("").reduce((e,u)=>e+Number.parseInt(u),0);return t}function g(n){const t=n.split("-");if(t.length<3)return 0;const e=Number.parseInt(t[2]);return f(e)}function p(n){const e=n.replace(/[^0-9]/g,"").split("").map(Number).reduce((u,r)=>u+r,0);return f(e)}function m(n){return n.replace(/[^0-9]/g,"").split("").map(Number).filter(t=>t>=1&&t<=9)}function b(n){return{1:"Sun (Surya)",2:"Moon (Chandra)",3:"Jupiter (Guru)",4:"Rahu",5:"Mercury (Budh)",6:"Venus (Shukra)",7:"Ketu",8:"Saturn (Shani)",9:"Mars (Mangal)"}[n]||"Unknown"}function C(n,t,e,u){const r=c(n),o=p(t),a=c(e),s=p(u),i=Math.abs(r+o-(a+s)),l=18;return Math.round((l-i)/l*100)}function S(n,t=[1,5,6,9]){const e=[],u=["a","e","i","o","u","aa","ee"],r=["a","i","an","in","on","al","el"];for(const a of r){const s=n+a,i=c(s);if(t.includes(i)&&!e.find(l=>l.name===s)&&e.push({name:s,number:i}),e.length>=5)break}if(n.length>3){const a=n.slice(0,-1),s=c(a);t.includes(s)&&e.push({name:a,number:s})}const o=n.slice(-1).toLowerCase();if(u.includes(o)){const a=n+o,s=c(a);t.includes(s)&&e.push({name:a,number:s})}return e.slice(0,5)}export{g as a,p as b,c,h as d,b as e,C as f,S as g,m as h,f as r};
